CREATE TABLE IF NOT EXISTS `meta_lead_capture_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `setting_name` varchar(100) NOT NULL, `setting_value` text NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_meta_setting` (`setting_name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `meta_lead_capture_settings` (`setting_name`,`setting_value`) VALUES ('enabled','0'),('app_id',''),('app_secret',''),('page_id',''),('page_access_token',''),('verify_token',''),('api_version',''),('default_status','New'),('owner_ids','');
CREATE TABLE IF NOT EXISTS `meta_lead_capture_audit` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `meta_lead_id` varchar(150) DEFAULT NULL, `page_id` varchar(100) DEFAULT NULL, `form_id` varchar(150) DEFAULT NULL, `event_type` varchar(40) NOT NULL, `payload_hash` char(64) DEFAULT NULL, `crm_record_type` varchar(20) DEFAULT NULL, `crm_record_id` int unsigned DEFAULT NULL, `status` varchar(30) NOT NULL, `error_message` varchar(500) DEFAULT NULL, `created_at` datetime NOT NULL, `processed_at` datetime DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_meta_event` (`meta_lead_id`,`event_type`), KEY `idx_meta_audit_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `meta_lead_capture_mapping` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `meta_lead_id` varchar(150) NOT NULL, `page_id` varchar(100) DEFAULT NULL, `form_id` varchar(150) DEFAULT NULL, `crm_client_id` int unsigned DEFAULT NULL, `normalized_phone` varchar(30) DEFAULT NULL, `normalized_email` varchar(190) DEFAULT NULL, `status` varchar(30) NOT NULL, `raw_field_data` mediumtext, `created_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_meta_lead_id` (`meta_lead_id`), KEY `idx_meta_phone` (`normalized_phone`), KEY `idx_meta_email` (`normalized_email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `meta_lead_capture_round_robin` (`id` tinyint unsigned NOT NULL, `last_owner_id` int unsigned NOT NULL DEFAULT 0, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `meta_lead_capture_round_robin` (`id`,`last_owner_id`,`updated_at`) VALUES (1,0,UTC_TIMESTAMP());
